<script lang="ts">
 import{onMount}from'svelte';
 import{invalidateAll}from'$app/navigation';
 import type{AppData}from'#lib/client/types.ts';
 import type{AssistantSource}from'#lib/client/assistant.ts';
 import{sourceReady}from'#lib/client/assistant.ts';
 import{command,statuses}from'#lib/client/api.ts';
 import AssistantSources from'../AssistantSources.svelte';
 import ReferencePicker from'../ReferencePicker.svelte';
 let{data,revisionId,jobs=[],onclose}:{data:AppData;revisionId:string;jobs?:any[];onclose:()=>void}=$props();
 let dialog:HTMLDialogElement,prompt=$state(''),rightsId=$state(''),statement=$state(''),sources:AssistantSource[]=$state([]),busy=$state(false),refreshing=$state(false),error=$state(''),quote:any=$state(null),quotedFor=$state(''),accepted=$state(false),submittedId=$state('');
 const input=$derived({revision_id:revisionId,prompt:prompt.trim(),reference_document_ids:sources.map(row=>row.documentId),reference_preview_job_ids:sources.map(row=>row.preview?.job_id??''),rights_evidence_version_id:rightsId,rights_statement:statement.trim()});
 const fingerprint=$derived(JSON.stringify(input));
 const currentJobs=$derived(jobs.filter(job=>job.revision_id===revisionId));
 $effect(()=>{if(quote&&quotedFor!==fingerprint){quote=null;accepted=false;}});
 onMount(()=>{dialog.showModal();return()=>dialog.close();});
 function validate(){if(input.prompt.length<8)throw Error('Den gewünschten Bildeindruck mit mindestens acht Zeichen beschreiben.');if(!rightsId||statement.trim().length<20)throw Error('Einen verfügbaren Nutzungsnachweis und den persönlich geprüften Nutzungsumfang angeben.');if(sources.length>2||sources.some(row=>!row.includeImage||!sourceReady(row)||!row.preview?.job_id))throw Error('Für jede gewählte Quelle den sichtbaren Bildinhalt aktivieren und genau diese Seite als kleine Bildreferenz fertig vorbereiten. Nicht benötigte Quellen entfernen.');}
 async function estimate(event:SubmitEvent){event.preventDefault();error='';busy=true;quote=null;accepted=false;try{validate();const key=fingerprint,result=await command('planning.visualization.quote',undefined,input);if(fingerprint===key){quote=result;quotedFor=key;}}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function generate(){error='';if(!quote||quotedFor!==fingerprint||!accepted)return;busy=true;try{validate();const result=await command('planning.visualization.request',quote.id,{...input,cost_acknowledged:true,approved_maximum:quote.estimatedMaxCost,request_hash:quote.requestHash},Number(quote.version));submittedId=result.id;quote=null;accepted=false;await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function refresh(){refreshing=true;error='';try{await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{refreshing=false;}}
 function cost(value:unknown){const number=Number(value);return Number.isFinite(number)?new Intl.NumberFormat('de-DE',{minimumFractionDigits:2,maximumFractionDigits:6}).format(number):'–';}
 function download(job:any){const result=job.result;return result?.documentId&&result.documentVersionId?`/api/v1/documents/${result.documentId}/download?version=${result.documentVersionId}`:null;}
</script>

<dialog bind:this={dialog} oncancel={onclose} aria-labelledby="visualization-title">
 <header><span>BILDIDEE · MIT KONKRETEM KOSTENLIMIT</span><h2 id="visualization-title">Eine Richtung sichtbar machen.</h2><p>Beschreiben Sie Atmosphäre, Farben und Umgebung. Das Konzeptbild wird separat gespeichert. Maße, Bauteile und wörtliche Inschriften bleiben im Plan erhalten.</p></header>
 <div class="content">
  {#if error}<p class="alert danger" role="alert">{error}</p>{/if}
  {#if submittedId}<p class="alert" role="status">Der Bildauftrag wurde für diesen gespeicherten Planstand angelegt. Den Abschluss können Sie unten ausdrücklich abfragen.</p>{/if}
  <form onsubmit={estimate}><fieldset disabled={busy}>
   <label>Bildeindruck<textarea bind:value={prompt} minlength="8" maxlength="2000" rows="4" required placeholder="Zum Beispiel ruhiger Innenraum, warmes Tageslicht und eine zurückhaltende Natursteinoberfläche"></textarea></label>
   <AssistantSources {data} bind:rows={sources} disabled={busy}/>
   <p class="hint">Für ein Konzeptbild werden nur die ausdrücklich ausgewählten, fertig vorbereiteten Bildseiten mitgegeben. Ohne zusätzliche Quelle dienen die gespeicherten Planungsdaten als Orientierung.</p>
   <label for="visualization-rights">Verfügbarer Nutzungsnachweis</label><ReferencePicker id="visualization-rights" reference="document-versions" value={rightsId} initial={(data.related?.documents??[]).map((d:any)=>({id:d.version_id??d.document_version_id??d.id,name:d.name??d.original_name??'Nachweis'}))} required onchange={value=>rightsId=value}/>
   <label class="statement">Persönlich geprüfter Nutzungsumfang<textarea bind:value={statement} minlength="20" maxlength="3000" rows="3" required placeholder="Welche Inhalte dürfen für diesen Zweck an den Bilddienst übermittelt und als Konzept verwendet werden?"></textarea></label>
   <button type="submit" class="btn" disabled={busy}>{busy?'Wird geprüft …':'Kosten vorab prüfen'}</button>
  </fieldset></form>
  {#if quote}<section class="cost-preview" aria-labelledby="cost-title"><p class="eyebrow">VERBINDLICHE AUSWAHL VOR DEM START</p><p>Maximale Reservierung</p><h3 id="cost-title">Bis zu {cost(quote.estimatedMaxCost)} {quote.currency}</h3><p>{quote.size??'1024x1024'} Pixel · Konzeptqualität · {quote.preferredModel}{#if quote.fallbackModel} · Ersatzmodell {quote.fallbackModel}{/if}</p><p>Der Betrag gilt für die gerade geprüften Angaben und das hinterlegte Anbieterprofil. Die tatsächliche Nutzung kann geringer ausfallen. Eine Änderung erfordert eine neue Kostenvorschau.</p>{#if quote.protectedContent}<p class="protected">Dieser Plan enthält geschützte Bestandsinschrift. Das erzeugte Bild bleibt intern. Eine Kundenfassung benötigt anschließend geprüftes Compositing mit erhaltenen Originalpixeln.</p>{/if}<label class="check"><input type="checkbox" bind:checked={accepted} disabled={busy}/> Ich bestätige diesen einzelnen kostenpflichtigen Bildauftrag bis zum oben genannten Betrag.</label><button type="button" class="btn primary" disabled={busy||!accepted} onclick={generate}>{busy?'Auftrag wird angelegt …':'Konzeptbild kostenpflichtig anfordern'}</button></section>{/if}
  <section class="results"><div class="result-heading"><h3>Bildaufträge dieses Planstands</h3><button type="button" class="btn" disabled={refreshing||busy} onclick={refresh}>{refreshing?'Wird aktualisiert …':'Status aktualisieren'}</button></div>{#each currentJobs as job}<article><strong>{statuses[job.status]??'Status prüfen'}</strong>{#if job.last_error}<p class="job-error">{job.last_error}</p>{/if}{#if job.result?.actualCost!==undefined}<p>Tatsächliche Nutzung: {cost(job.result.actualCost)} USD</p>{/if}{#if download(job)}<a href={download(job)!} target="_blank" rel="noreferrer" data-sveltekit-reload><img src={download(job)!+'&inline=1'} alt="Gespeichertes KI-Konzeptbild dieses Planstands" loading="lazy"/></a><p>KI-Konzept · keine technische Zeichnung{#if job.result?.protectedContentRequiresComposite} · vor Kundenverwendung Originalpixel schützen{/if}</p><a class="btn" href={download(job)!} download data-sveltekit-reload>Gespeichertes Konzept herunterladen</a>{/if}</article>{:else}<p>Für diese Revision liegt noch kein Konzeptbildauftrag vor.</p>{/each}</section>
 </div><footer><p>Die technische Kundenansicht und das 4K-Render stehen weiterhin unter „Prüfen“ bereit.</p><button type="button" class="btn" disabled={busy} onclick={onclose}>Zurück zum Plan</button></footer>
</dialog>

<style>
dialog{width:min(700px,94vw);max-height:92dvh;padding:0;border:1px solid var(--line,#d9deda);border-radius:8px;background:var(--paper,#fff);color:var(--ink,#202522)}dialog::backdrop{background:#15231fcc;backdrop-filter:blur(3px)}header{padding:26px 30px 22px;background:var(--paper);border-bottom:1px solid var(--line,#d9deda)}header>span,.eyebrow{font-size:11px;letter-spacing:.1em;color:var(--muted,#657167)}h2{font-size:28px;font-weight:500;letter-spacing:-.8px;margin:12px 0}p{font-size:13px;line-height:1.7;color:var(--muted,#657167);margin:10px 0}.content{padding:24px 30px;max-height:63dvh;overflow:auto}fieldset{padding:0;margin:0;border:0;min-width:0}label{display:block;font-size:13px;line-height:1.6;margin-bottom:8px;color:var(--muted)}textarea{box-sizing:border-box;width:100%;padding:11px;min-height:44px;margin:7px 0 14px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);font:inherit;font-size:14px}.statement{margin-top:20px}.content :global(select){width:100%;min-height:44px;padding:10px;background:var(--paper);border:1px solid var(--line);border-radius:4px;color:var(--ink);font:inherit;font-size:14px}.content :global(.field-help){font-size:12px;line-height:1.7}.hint{padding-left:12px;border-left:2px solid var(--line);font-size:12px;margin:15px 0 20px}.cost-preview{padding:20px;margin:24px 0;border:1px solid var(--line);background:var(--wash);border-radius:5px}h3{font-size:17px;font-weight:550;line-height:1.4}.cost-preview h3{font-size:25px}.cost-preview .eyebrow{margin:0 0 8px}.protected{background:var(--warning-wash);padding:12px;border:1px solid var(--line)}.check{display:flex;gap:10px;align-items:start;margin:20px 0}.check input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--forest)}.btn{min-height:44px;font-size:12px;white-space:normal}.btn.primary{background:var(--forest);color:var(--on-accent,#fff)}.alert{padding:13px;border:1px solid var(--line);background:var(--wash);white-space:pre-wrap}.alert.danger{border-color:var(--line);background:var(--danger-wash);color:var(--danger)}.results{border-top:1px solid var(--line,#d9deda);margin-top:27px;padding-top:20px}.result-heading{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.results article{padding:18px 0;border-bottom:1px solid var(--line,#d9deda)}.results strong{font-size:14px}.results img{display:block;width:100%;max-height:320px;object-fit:contain;margin:14px 0;background:white}.job-error{color:var(--danger);white-space:pre-wrap}footer{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px 30px;border-top:1px solid var(--line,#d9deda)}footer p{font-size:12px;max-width:330px;margin:0}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--forest);outline-offset:3px}@media(max-width:600px){header,.content{padding:22px}h2{font-size:25px}.content{max-height:61dvh}textarea,.content :global(select){font-size:16px}.btn{min-height:48px}footer{padding:18px 22px;flex-wrap:wrap}footer .btn{width:100%}}
</style>
